package com.stocksense.inventory.stock; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*; public interface StockBalanceRepository extends JpaRepository<StockBalance,Long>{ List<StockBalance> findByProductId(Long productId); List<StockBalance> findByLocationWarehouseId(Long warehouseId); Optional<StockBalance> findByProductIdAndLocationId(Long productId,Long locationId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from StockBalance s where s.product.id=:p and s.location.id=:l") Optional<StockBalance> lock(@Param("p") Long productId,@Param("l") Long locationId); }